examples.template:
MonarchSchemaDrivenForm(
    form,
    values: $answers,
    labels: MonarchSchemaDrivenFormLabels(submit: {{submitLabel}})
) { answers in
    try await send(answers)
}
.environment(\.locale, Locale(identifier: {{locale}}))

examples.code:
MonarchSchemaDrivenForm(
    form,
    values: $answers,
    labels: MonarchSchemaDrivenFormLabels(submit: "Book")
) { answers in
    try await send(answers)
}
.environment(\.locale, Locale(identifier: "en-GB"))

examples.setup:
@State private var saved: [String: MonarchFormFieldValue] = ["workspace": .text("Rook")]
@State private var answers: [String: MonarchFormFieldValue] = ["workspace": .text("Rook")]
private let form = [
    MonarchFormFieldDefinition(id: "workspace", type: .shortText, label: "Workspace name", isRequired: true)
]

examples.code:
NavigationStack {
    MonarchSchemaDrivenForm(
        form,
        values: $answers,
        isDirty: answers != saved,
        onSubmit: { values in saved = values },
        onDiscard: { answers = saved }
    )
    .monarchCanvas()
    .navigationTitle("Workspace")
}
